# Check which taxa appear in each file, and examine headers more closely
for faa in sorted(glob.glob('*.faa')):
    with open(faa, 'r') as f:
        headers = [line.strip() for line in f if line.startswith('>')]
    taxa_in_file = [h.lstrip('>').split()[0] for h in headers]
    print(f"{faa}: {taxa_in_file}")

# Also look at a file with Xlae to see full header format
print("\n--- Checking Xlae headers ---")
for faa in sorted(glob.glob('*.faa')):
    with open(faa, 'r') as f:
        for line in f:
            if line.startswith('>') and 'Xlae' in line:
                print(f"{faa}: {line.strip()}")
